"""Generated by the NL to Flow Diagram Encoder Pipeline."""

words = ['hello', 'again', 'similar', 'simulate', 'halo', 'sibner']

n = (len(words) - 1)

for i in range(0, n):
    for j in range(0, (n - i)):
        if (words[j] > words[(j + 1)]):
            temp = words[j]
            words[j] = words[(j + 1)]
            words[(j + 1)] = temp

print(words)
